/// Modifiers: readonly
pub async fn signed_get(&self, url: String, date: String, authorization: String, max_seconds: String) -> std::result::Result<(i64, String, String), std::boxed::Box<dyn std::error::Error>> {
        if self.dry_run.is_dry_run() {
            eprintln!("[dry-run] SignedGet");
panic!("no mock data available for dry-run operation: SignedGet")
} else {
            let output = std::process::Command::new(curl_program().invocation())
    .arg("-sS")
    .arg("--max-time")
    .arg(&format!("{}", max_seconds))
    .arg("-H")
    .arg(&format!("date: {}", date))
    .arg("-H")
    .arg(&format!("authorization: {}", authorization))
    .arg("-D")
    .arg("/dev/stderr")
    .arg("-w")
    .arg("\n%{http_code}")
    .arg(&format!("{}", url))
    .current_dir(self.working_dir.as_deref().unwrap_or("."))
    .output()?;
let stdout = String::from_utf8_lossy(&output.stdout).to_string();
let exit_code = output.status.code().unwrap_or(-1);
match exit_code {
    0 => { let stderr = String::from_utf8_lossy(&output.stderr).to_string();
Ok(((output.status.code().unwrap_or(-1) as i64), stdout.clone(), stderr.clone())) },
    _ => { let stderr = String::from_utf8_lossy(&output.stderr).to_string();
Ok(((output.status.code().unwrap_or(-1) as i64), stdout.clone(), stderr.clone())) },
}
}
}

pub async fn signed_post_json(&self, url: String, date: String, authorization: String, max_seconds: String, content_sha256: String, retry_token: String, body: String) -> std::result::Result<(i64, String, String), std::boxed::Box<dyn std::error::Error>> {
        if self.dry_run.is_dry_run() {
            eprintln!("[dry-run] SignedPostJson");
panic!("no mock data available for dry-run operation: SignedPostJson")
} else {
            let mut output = std::process::Command::new(curl_program().invocation())
    .arg("-sS")
    .arg("--max-time")
    .arg(&format!("{}", max_seconds))
    .arg("-X")
    .arg("POST")
    .arg("-H")
    .arg(&format!("date: {}", date))
    .arg("-H")
    .arg(&format!("authorization: {}", authorization))
    .arg("-H")
    .arg("content-type: application/json")
    .arg("-H")
    .arg(&format!("x-content-sha256: {}", content_sha256))
    .arg("-H")
    .arg(&format!("opc-retry-token: {}", retry_token))
    .arg("--data-binary")
    .arg("@-")
    .arg("-D")
    .arg("/dev/stderr")
    .arg("-w")
    .arg("\n%{http_code}")
    .arg(&format!("{}", url))
    .current_dir(self.working_dir.as_deref().unwrap_or("."))
    .stdin(std::process::Stdio::piped())
    .stdout(std::process::Stdio::piped())
    .stderr(std::process::Stdio::piped())
    .spawn()?;
{
    use std::io::Write;
    if let Some(mut stdin) = output.stdin.take() {
        stdin.write_all(body.as_bytes())?;
    }
}
let output = output.wait_with_output()?;
let stdout = String::from_utf8_lossy(&output.stdout).to_string();
let exit_code = output.status.code().unwrap_or(-1);
match exit_code {
    0 => { let stderr = String::from_utf8_lossy(&output.stderr).to_string();
Ok(((output.status.code().unwrap_or(-1) as i64), stdout.clone(), stderr.clone())) },
    _ => { let stderr = String::from_utf8_lossy(&output.stderr).to_string();
Ok(((output.status.code().unwrap_or(-1) as i64), stdout.clone(), stderr.clone())) },
}
}
}
