pub fn curl_dumped_header_value(dump: String, name: String) -> String {
    {
        let prefix = v1_rt::concat(curl_ascii_lower_from(name, 0, "".to_string()), ":".to_string());
let n = v1_rt::string_length(&prefix);
Rc::new(dump.clone().split(&"\n".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).iter().cloned().fold("".to_string(), |acc: String, line: String| if ((v1_rt::string_length(&line) > n.clone()) && (curl_ascii_lower_from(v1_rt::substring(&line, 0, n.clone()), 0, "".to_string()) == prefix.clone())) {
            v1_rt::trim(v1_rt::substring(&line, n.clone(), v1_rt::string_length(&line)))
        } else {
            acc
        })
}
}

pub fn curl_body_before_http_code(stdout: String) -> String {
    {
        let lines = Rc::new(stdout.clone().split(&"\n".to_string()).map(|s| s.to_string()).collect::<Vec<_>>());
let n = (lines.clone().len() as i64);
if (n.clone() <= 1) {
            "".to_string()
        } else {
            Rc::new(v1_rt::list_take(&lines.clone(), v1_rt::int_sub(n.clone(), 1))).join(&"\n".to_string())
        }
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct CurlSignedRun {
    pub exit_code: i64,
    pub stdout: String,
    pub stderr: String,
}

pub async fn curl_http_signature_get(url: String, date: String, authorization: String, max_time: Second, net: &Network, curl_http_signature: &Curl__HttpSignature) -> std::result::Result<Rc<CurlSignedRun>, std::boxed::Box<dyn std::error::Error>> {
    let run = curl_http_signature.signed_get(url.clone(), date.clone(), authorization.clone(), (crate::std_measure::second_count(max_time)).to_string()).await?;
Ok(Rc::new(CurlSignedRun {
    exit_code: run.0.clone(),
    stdout: run.1.clone(),
    stderr: run.2.clone(),
}))
}

pub async fn curl_http_signature_post_json(url: String, date: String, authorization: String, max_time: Second, content_sha256: String, retry_token: String, body: String, net: &Network, curl_http_signature: &Curl__HttpSignature) -> std::result::Result<Rc<CurlSignedRun>, std::boxed::Box<dyn std::error::Error>> {
    let run = curl_http_signature.signed_post_json(url.clone(), date.clone(), authorization.clone(), (crate::std_measure::second_count(max_time)).to_string(), content_sha256.clone(), retry_token.clone(), body.clone()).await?;
Ok(Rc::new(CurlSignedRun {
    exit_code: run.0.clone(),
    stdout: run.1.clone(),
    stderr: run.2.clone(),
}))
}

